        ...this.getWorldsettingsCategories('master')
      };
      const category = categories[categoryKey];
      if (!category) return value;
      try {
        // 1. 先尝试从项目本身获取desc
        const itemDesc = category.items[itemKey]?.desc;
        if (itemDesc && itemDesc[value] !== undefined) {
          return itemDesc[value];
        }

        // 2. 如果项目没有desc或没找到值，尝试从分类获取通用desc
        if (category.desc && category.desc[value] !== undefined) {
          return category.desc[value];
        }

        // 3. 对于没有描述但有标准值模式的情况
        const standardValues = {
          'default': '默认',
          'never': '无',
          'rare': '很少',
          'uncommon': '较少',
          'often': '较多',
          'mostly': '很多',
          'always': '大量',
          'insane': '疯狂'
        };
        if (standardValues[value]) {
          return standardValues[value];
        }

        // 4. 如果都没有，返回原始值
