    // 预加载图片
    preloadImages() {
      this.imagesLoading = true;
      this.imageLoadProgress = 0;

      // 从配置中获取图片资源名称
      const categories = this.worldSettingsData.forest.WORLDGEN_GROUP;
      const worldgenAtlasName = Object.values(categories)[0]?.atlas?.name || 'worldgen_customization';
      const worldsettingsCategories = this.worldSettingsData.forest.WORLDSETTINGS_GROUP;
      const worldsettingsAtlasName = Object.values(worldsettingsCategories)[0]?.atlas?.name || 'worldsettings_customization';

      // 尝试多种可能的路径
      const baseUrls = ['/static/misc/', '/dist/misc/', '/assets/misc/', '/'];
      const worldgenPaths = baseUrls.map(base => `${base}${worldgenAtlasName}.webp`);
      const worldsettingsPaths = baseUrls.map(base => `${base}${worldsettingsAtlasName}.webp`);

      // 尝试加载一个图片，从多个可能的路径
      const tryLoadImage = (paths, type) => {
        return new Promise(resolve => {
          let loaded = false;
          let currentIndex = 0;
          const tryNextPath = () => {
            if (currentIndex >= paths.length) {
              resolve(''); // 所有路径都失败了
              return;
            }
            const path = paths[currentIndex];
            const img = new Image();
            img.onload = () => {
              loaded = true;
              resolve(path);
            };
            img.onerror = () => {
              currentIndex++;
              if (!loaded) {
                tryNextPath();
              }
            };
            img.src = path;
          };
          tryNextPath();
        });
      };

      // 并行尝试加载两种图片
      Promise.all([tryLoadImage(worldgenPaths, 'worldgen'), tryLoadImage(worldsettingsPaths, 'worldsettings')]).then(([worldgenPath, worldsettingsPath]) => {
        this.imagePaths.worldgen = worldgenPath;
        this.imagePaths.worldsettings = worldsettingsPath;
        if (!worldgenPath || !worldsettingsPath) {
          this.showError('无法加载图片资源，请检查网络或联系管理员');
          this.imageLoadErrors.push('图片资源路径错误');
        }
        this.imagesLoading = false;
        this.imageLoadProgress = 100;
      }).catch(() => {
        this.imagesLoading = false;
        this.imageLoadProgress = 100;
        this.showError('加载图片资源时发生错误');
      });

      // 设置超时处理，防止图片长时间无法加载
      setTimeout(() => {
        if (this.imagesLoading) {
          this.imagesLoading = false;
          this.showError('图标加载超时，请检查网络连接');
        }
      }, 10000);
    },
    // 获取图片路径
    getItemAtlasPath(isWorldgen) {
      return isWorldgen ? this.imagePaths.worldgen : this.imagePaths.worldsettings;
    },
    // 获取项目的选项描述
    getItemDescOptions(category, itemKey) {
      if (!category || !category.items || !category.items[itemKey]) {
        console.warn(`找不到分类或项目: ${itemKey}`);
        return {
          'default': '默认'
        };
      }

      // 1. 先尝试从项目本身获取desc
      const itemDesc = category.items[itemKey].desc;
      if (itemDesc && typeof itemDesc === 'object') {
        return itemDesc;
      }

      // 2. 如果项目没有desc，尝试从分类获取通用desc
      if (category.desc && typeof category.desc === 'object') {
        return category.desc;
      }

      // 3. 如果都没有或格式不正确，提供默认值
      console.warn(`项目 ${itemKey} 没有有效的选项描述`);
      return {
        'default': '默认值',
        'none': '无',
        'rare': '很少',
        'often': '较多'
      };
    },
    // 添加重置默认选项方法
    resetItemToDefault(world, settingType, categoryKey, itemKey) {
      const defaultValue = 'default';
      // 设置值为default
      if (world[settingType][categoryKey] && world[settingType][categoryKey][itemKey] !== undefined) {
        this.$set(world[settingType][categoryKey], itemKey, defaultValue);
      }
    }
  },
  created() {
    // 判断是否为编辑模式
    const {
      id
    } = this.$route.query;
    if (id) {
      this.isEdit = true;
      this.saveId = parseInt(id);
      this.loadSaveData();
    } else {
      // 默认添加一个森林世界
      this.addWorld('master');
    }

    // 预加载图片
    this.preloadImages();
  }
};
